from pathlib import Path
import re
c=Path(__file__).resolve().parent
rows=[]
for scene in ['boxes','hoist']:
 a,b=[dict(re.findall(r'(\w+)=([\d.]+)',(c/phase/(scene+'.metrics.txt')).read_text())) for phase in ['before','after']]
 rows.append(f"<tr><td>{scene}</td><td>{a['mean_ms']} ms / {a['mean_fps']} FPS</td><td>{b['mean_ms']} ms / {b['mean_fps']} FPS</td><td>{(float(b['mean_ms'])/float(a['mean_ms'])-1)*100:+.1f}%</td><td>{int(b['image_cpu_bytes'])/1e6:.1f} MB</td></tr>")
